<template><div class="app-container"><div class="head"><h2>巡店资料与运营</h2><el-button @click="load">刷新</el-button></div>
<el-row :gutter="16" class="cards"><el-col v-for="c in cards" :key="c.label" :span="4"><el-card shadow="never"><b>{{c.value}}</b><span>{{c.label}}</span></el-card></el-col></el-row>
<el-tabs v-model="tab">
<el-tab-pane label="整改任务" name="rectifications"><el-table :data="rectificationList" border><el-table-column prop="storeName" label="门店"/><el-table-column prop="title" label="问题"/><el-table-column prop="severity" label="等级"/><el-table-column prop="assigneeId" label="负责人"/><el-table-column prop="status" label="状态"/><el-table-column prop="dueTime" label="截止时间"/><el-table-column label="操作" width="180"><template slot-scope="{row}"><template v-if="row.status==='SUBMITTED'"><el-button type="success" size="mini" @click="review(row,true)">通过</el-button><el-button type="danger" size="mini" @click="review(row,false)">退回</el-button></template></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane label="资料中心" name="media"><div class="toolbar"><el-select v-model="taskId" filterable placeholder="选择巡店任务"><el-option v-for="v in visits" :key="v.id" :label="`${v.storeName} - ${v.title}`" :value="v.id"/></el-select><el-button type="primary" @click="loadMedia">查询资料</el-button></div><el-table :data="mediaList" border><el-table-column prop="mediaType" label="类型"/><el-table-column prop="fileName" label="文件"/><el-table-column prop="fileSize" label="大小"/><el-table-column prop="status" label="上传状态"/><el-table-column prop="capturedAt" label="采集时间"/><el-table-column label="证据"><template slot-scope="{row}"><el-link v-if="row.storageUrl" :href="row.storageUrl" target="_blank" type="primary">查看</el-link></template></el-table-column></el-table></el-tab-pane>
</el-tabs></div></template>
<script>import{ visitOperations, rectifications, reviewRectification, storeVisits, visitMedia }from'@/api/inspection';const d=v => (v&&v.data)||v||[];export default{ name:'VisitOperations', data:() => ({ tab:'rectifications', summary:{}, rectificationList:[], visits:[], mediaList:[], taskId:null }), computed:{ cards(){return[{ label:'任务', value:this.summary.taskCount||0 }, { label:'完成率', value:this.p(this.summary.completionRate) }, { label:'覆盖门店', value:this.summary.storeCount||0 }, { label:'问题', value:this.summary.problemCount||0 }, { label:'闭环率', value:this.p(this.summary.rectificationRate) }, { label:'逾期', value:this.summary.overdueCount||0 }]} }, created(){this.load()}, methods:{ p(v){return Math.round((v||0)*100)+'%'}, async load(){const r=await Promise.all([visitOperations(30), rectifications(), storeVisits()]);this.summary=(r[0]&&r[0].data)||r[0]||{};this.rectificationList=d(r[1]);this.visits=d(r[2])}, async review(row, passed){await reviewRectification(row.id, passed, passed?'':'整改证据未达到要求');this.load()}, async loadMedia(){if(!this.taskId)return this.$message.warning('请选择巡店任务');this.mediaList=d(await visitMedia(this.taskId))} } }</script>
<style scoped>.head{display:flex;justify-content:space-between;align-items:center}.head h2{margin-top:0}.cards{margin-bottom:18px}.el-card b,.el-card span{display:block}.el-card b{font-size:26px}.el-card span{margin-top:8px;color:#909399}.toolbar{margin-bottom:16px}.toolbar .el-select{width:360px;margin-right:10px}</style>
